import{_ as o,I as r,o as i,c as s,b6 as a,J as d}from"./chunks/framework.COUcLbTA.js";const f=JSON.parse('{"title":"数据可视化与仪表盘","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/5-data/data-visualization.md","filePath":"zh-cn/appendix/5-data/data-visualization.md"}'),n={name:"zh-cn/appendix/5-data/data-visualization.md"};function h(b,t,c,g,p,u){const e=r("ChartTypeSelectorDemo"),l=r("DashboardLayoutDemo");return i(),s("div",null,[t[0]||(t[0]=a('<h1 id="数据可视化与仪表盘" tabindex="-1">数据可视化与仪表盘 <a class="header-anchor" href="#数据可视化与仪表盘" aria-label="Permalink to “数据可视化与仪表盘”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>一张好的图表胜过一千行数据。</strong> 数据可视化是将抽象的数字转化为直观的视觉表达，让人能在几秒内理解数据背后的故事。从 Excel 图表到 Grafana 监控大屏，可视化无处不在。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>图表选择</strong>：根据数据目的选择最合适的图表类型</li><li><strong>可视化原则</strong>：掌握数据可视化的核心设计原则</li><li><strong>仪表盘设计</strong>：了解不同类型仪表盘的布局模式</li><li><strong>工具生态</strong>：熟悉主流可视化工具的定位和选型</li><li><strong>常见陷阱</strong>：避免误导性图表和常见的可视化错误</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>图表类型选择</td><td>比较、趋势、占比、分布、关系</td></tr><tr><td><strong>第 2 章</strong></td><td>可视化设计原则</td><td>数据墨水比、一致性、可读性</td></tr><tr><td><strong>第 3 章</strong></td><td>仪表盘布局</td><td>概览型、对比型、下钻型、实时型</td></tr><tr><td><strong>第 4 章</strong></td><td>工具选型</td><td>ECharts、D3、Grafana、Metabase</td></tr><tr><td><strong>第 5 章</strong></td><td>常见陷阱</td><td>截断坐标轴、3D 饼图、颜色滥用</td></tr></tbody></table><hr><h2 id="_0-全景图-为什么需要可视化" tabindex="-1">0. 全景图：为什么需要可视化？ <a class="header-anchor" href="#_0-全景图-为什么需要可视化" aria-label="Permalink to “0. 全景图：为什么需要可视化？”">​</a></h2><p>人类大脑处理视觉信息的速度比处理文字快 6 万倍。一张折线图能让你在 1 秒内看出&quot;上个月销售额在下降&quot;，而同样的信息如果用表格呈现，你可能需要 30 秒才能得出结论。</p><p>可视化的核心价值：</p><ul><li><strong>发现模式</strong>：趋势、周期、异常值在图表中一目了然</li><li><strong>辅助决策</strong>：让非技术人员也能理解数据，参与决策</li><li><strong>沟通效率</strong>：一图胜千言，减少数据解读的歧义</li></ul><div class="tip custom-block"><p class="custom-block-title">可视化 ≠ 好看</p><p>可视化的目标是<strong>传达信息</strong>，不是炫技。一个朴素但准确的柱状图，远比一个花哨但难以理解的 3D 图表更有价值。</p></div><hr><h2 id="_1-图表类型选择-用对图表讲对故事" tabindex="-1">1. 图表类型选择：用对图表讲对故事 <a class="header-anchor" href="#_1-图表类型选择-用对图表讲对故事" aria-label="Permalink to “1. 图表类型选择：用对图表讲对故事”">​</a></h2><p>选择图表的第一步不是&quot;我喜欢什么图表&quot;，而是&quot;我想传达什么信息&quot;。不同的数据目的对应不同的最佳图表类型。</p>',15)),d(e),t[1]||(t[1]=a('<h3 id="图表选择速查表" tabindex="-1">图表选择速查表 <a class="header-anchor" href="#图表选择速查表" aria-label="Permalink to “图表选择速查表”">​</a></h3><table tabindex="0"><thead><tr><th>数据目的</th><th>推荐图表</th><th>不推荐</th><th>原因</th></tr></thead><tbody><tr><td>比较大小</td><td>柱状图、条形图</td><td>饼图</td><td>人眼对长度差异比角度差异更敏感</td></tr><tr><td>展示趋势</td><td>折线图、面积图</td><td>柱状图</td><td>折线的连续性暗示时间的连续性</td></tr><tr><td>展示占比</td><td>饼图（≤5 类）、堆叠柱状图</td><td>3D 饼图</td><td>3D 透视会扭曲面积比例</td></tr><tr><td>展示分布</td><td>直方图、箱线图</td><td>折线图</td><td>分布需要看频率，不是趋势</td></tr><tr><td>展示关系</td><td>散点图、气泡图</td><td>柱状图</td><td>两个连续变量的关系需要二维空间</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一个简单的决策规则</p><ul><li><strong>一个变量</strong> → 直方图（分布）或数字卡片（KPI）</li><li><strong>两个变量</strong> → 折线图（时间 vs 数值）或散点图（数值 vs 数值）</li><li><strong>多个类别</strong> → 柱状图（比较）或饼图（占比，≤5 类）</li><li><strong>多维度</strong> → 雷达图或平行坐标图</li></ul></div><hr><h2 id="_2-可视化设计原则" tabindex="-1">2. 可视化设计原则 <a class="header-anchor" href="#_2-可视化设计原则" aria-label="Permalink to “2. 可视化设计原则”">​</a></h2><p>Edward Tufte 在《The Visual Display of Quantitative Information》中提出了数据可视化的核心原则，至今仍是行业标准。</p><table tabindex="0"><thead><tr><th>原则</th><th>说明</th><th>反面案例</th></tr></thead><tbody><tr><td>数据墨水比</td><td>图表中用于展示数据的&quot;墨水&quot;占比应尽量高</td><td>过多的网格线、装饰性元素</td></tr><tr><td>最小化非数据元素</td><td>去除不传达信息的视觉元素</td><td>3D 效果、阴影、渐变背景</td></tr><tr><td>一致的比例尺</td><td>坐标轴从零开始，刻度均匀</td><td>Y 轴从 95 开始（夸大差异）</td></tr><tr><td>合理的颜色使用</td><td>用颜色编码信息，而非装饰</td><td>彩虹色（无序）表示有序数据</td></tr><tr><td>清晰的标注</td><td>标题、轴标签、图例缺一不可</td><td>没有单位、没有时间范围</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">颜色使用的三条规则</p><ol><li><strong>同一指标用同一颜色</strong>：收入在所有图表中都用蓝色，不要一会蓝一会绿</li><li><strong>有序数据用渐变色</strong>：温度从低到高用蓝→红渐变，不要用离散色</li><li><strong>考虑色盲友好</strong>：约 8% 的男性有红绿色盲，避免仅用红绿区分关键信息</li></ol></div><hr><h2 id="_2-可视化设计原则-让数据说话" tabindex="-1">2. 可视化设计原则：让数据说话 <a class="header-anchor" href="#_2-可视化设计原则-让数据说话" aria-label="Permalink to “2. 可视化设计原则：让数据说话”">​</a></h2><p>好的可视化不是&quot;好看&quot;，而是&quot;好懂&quot;。Edward Tufte 在《The Visual Display of Quantitative Information》中提出了几个经典原则，至今仍是可视化设计的黄金标准。</p><h3 id="_2-1-数据墨水比-data-ink-ratio" tabindex="-1">2.1 数据墨水比（Data-Ink Ratio） <a class="header-anchor" href="#_2-1-数据墨水比-data-ink-ratio" aria-label="Permalink to “2.1 数据墨水比（Data-Ink Ratio）”">​</a></h3><blockquote><p>图表中用于表达数据的&quot;墨水&quot;占总&quot;墨水&quot;的比例应该尽可能高。</p></blockquote><p>简单说：<strong>删掉一切不传达信息的元素</strong>。</p><table tabindex="0"><thead><tr><th>应该删掉的</th><th>应该保留的</th></tr></thead><tbody><tr><td>3D 效果、阴影、渐变</td><td>数据点、坐标轴标签</td></tr><tr><td>多余的网格线</td><td>关键参考线（如目标值）</td></tr><tr><td>装饰性图标</td><td>图例（当有多系列时）</td></tr><tr><td>花哨的背景色</td><td>清晰的标题和单位</td></tr></tbody></table><h3 id="_2-2-一致性原则" tabindex="-1">2.2 一致性原则 <a class="header-anchor" href="#_2-2-一致性原则" aria-label="Permalink to “2.2 一致性原则”">​</a></h3><ul><li><strong>颜色一致</strong>：同一个维度在不同图表中用同一种颜色（如&quot;收入&quot;始终用蓝色）</li><li><strong>比例一致</strong>：坐标轴从 0 开始（除非有充分理由），避免误导</li><li><strong>时间一致</strong>：时间轴的间隔应该均匀，不要跳跃</li></ul><h3 id="_2-3-可读性原则" tabindex="-1">2.3 可读性原则 <a class="header-anchor" href="#_2-3-可读性原则" aria-label="Permalink to “2.3 可读性原则”">​</a></h3><ul><li><strong>标题要说结论</strong>：不是&quot;月度销售额&quot;，而是&quot;销售额连续 3 个月下降&quot;</li><li><strong>标注关键点</strong>：在异常值、拐点处加标注，引导读者注意力</li><li><strong>控制信息密度</strong>：一张图表传达 1-2 个核心信息，不要塞太多</li></ul><div class="tip custom-block"><p class="custom-block-title">Tufte 的名言</p><p>&quot;Excellence in statistical graphics consists of complex ideas communicated with clarity, precision, and efficiency.&quot;（优秀的统计图形，是用清晰、精确、高效的方式传达复杂的想法。）</p></div><hr><h2 id="_3-仪表盘布局-不同场景-不同模式" tabindex="-1">3. 仪表盘布局：不同场景，不同模式 <a class="header-anchor" href="#_3-仪表盘布局-不同场景-不同模式" aria-label="Permalink to “3. 仪表盘布局：不同场景，不同模式”">​</a></h2><p>仪表盘（Dashboard）是多个图表的有机组合。好的仪表盘不是把图表堆在一起，而是根据使用场景选择合适的布局模式。</p>',23)),d(l),t[2]||(t[2]=a('<h3 id="四种常见布局模式" tabindex="-1">四种常见布局模式 <a class="header-anchor" href="#四种常见布局模式" aria-label="Permalink to “四种常见布局模式”">​</a></h3><table tabindex="0"><thead><tr><th>布局模式</th><th>核心结构</th><th>适用场景</th><th>设计要点</th></tr></thead><tbody><tr><td>全局概览型</td><td>KPI 卡片 + 趋势图 + 明细表</td><td>管理层日报、运营大盘</td><td>核心指标放最上方，一眼看到关键数字</td></tr><tr><td>对比分析型</td><td>左右对称布局</td><td>A/B 测试、同环比分析</td><td>保持对比维度一致，突出差异</td></tr><tr><td>下钻分析型</td><td>从汇总到明细逐层展开</td><td>销售分析、用户行为分析</td><td>支持点击交互，逐层深入</td></tr><tr><td>实时监控型</td><td>大数字 + 实时曲线 + 告警状态</td><td>双十一大屏、服务器监控</td><td>自动刷新，深色背景，适合投屏</td></tr></tbody></table><h3 id="仪表盘设计的-5-个原则" tabindex="-1">仪表盘设计的 5 个原则 <a class="header-anchor" href="#仪表盘设计的-5-个原则" aria-label="Permalink to “仪表盘设计的 5 个原则”">​</a></h3><ol><li><strong>先问&quot;谁在看&quot;</strong>：CEO 看战略指标，运营看过程指标，工程师看技术指标</li><li><strong>5 秒规则</strong>：用户应该在 5 秒内理解仪表盘的核心信息</li><li><strong>信息层次</strong>：最重要的放左上角（F 型阅读模式），次要的放下方</li><li><strong>减少滚动</strong>：一屏展示核心内容，避免用户需要滚动才能看到关键数据</li><li><strong>留白</strong>：不要塞满每一寸空间，适当留白让视觉更舒适</li></ol><div class="tip custom-block"><p class="custom-block-title">仪表盘 vs 报表</p><ul><li><strong>仪表盘</strong>：实时/准实时，交互式，面向监控和快速决策</li><li><strong>报表</strong>：定期生成（日/周/月），静态，面向详细分析和存档</li></ul><p>两者不是替代关系，而是互补关系。仪表盘发现问题，报表深入分析。</p></div><hr><h2 id="_4-工具选型-从代码到拖拽" tabindex="-1">4. 工具选型：从代码到拖拽 <a class="header-anchor" href="#_4-工具选型-从代码到拖拽" aria-label="Permalink to “4. 工具选型：从代码到拖拽”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>ECharts</td><td>JS 图表库</td><td>百度开源，图表类型丰富，中文文档完善</td><td>前端项目内嵌图表</td></tr><tr><td>D3.js</td><td>JS 可视化库</td><td>底层灵活，可定制任意可视化效果</td><td>高度定制化需求</td></tr><tr><td>Chart.js</td><td>JS 图表库</td><td>轻量简单，上手快</td><td>简单图表需求</td></tr><tr><td>Grafana</td><td>监控仪表盘</td><td>支持多数据源，实时刷新，告警集成</td><td>服务器/应用监控</td></tr><tr><td>Metabase</td><td>BI 工具</td><td>开源，SQL 查询 + 拖拽建图</td><td>业务数据分析</td></tr><tr><td>Superset</td><td>BI 工具</td><td>Apache 开源，支持大数据源</td><td>企业级数据探索</td></tr><tr><td>Tableau</td><td>商业 BI</td><td>拖拽式，交互能力强</td><td>企业级报表</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">怎么选？</p><ul><li><strong>开发者做项目内嵌图表</strong> → ECharts（功能全）或 Chart.js（轻量）</li><li><strong>需要高度定制的可视化</strong> → D3.js（学习曲线陡但无限可能）</li><li><strong>运维监控大屏</strong> → Grafana（行业标准）</li><li><strong>业务团队自助分析</strong> → Metabase（简单）或 Superset（功能强）</li></ul></div><hr><h2 id="_4-工具选型-从代码库到-bi-平台" tabindex="-1">4. 工具选型：从代码库到 BI 平台 <a class="header-anchor" href="#_4-工具选型-从代码库到-bi-平台" aria-label="Permalink to “4. 工具选型：从代码库到 BI 平台”">​</a></h2><p>可视化工具可以分为三个层次：底层绑定库、高层图表库、BI 平台。选择哪个取决于你的需求复杂度和团队技术能力。</p><h3 id="_4-1-代码级图表库" tabindex="-1">4.1 代码级图表库 <a class="header-anchor" href="#_4-1-代码级图表库" aria-label="Permalink to “4.1 代码级图表库”">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>语言/平台</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>开箱即用，图表类型丰富，中文文档完善</td><td>业务系统内嵌图表</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>底层灵活，可定制任何可视化效果</td><td>高度定制化的数据可视化</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>轻量简单，上手快</td><td>简单的图表需求</td></tr><tr><td>Matplotlib</td><td>Python</td><td>科学计算标准库，静态图表</td><td>数据分析、论文图表</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>交互式图表，支持 3D</td><td>数据探索、Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-bi-平台-无代码-低代码" tabindex="-1">4.2 BI 平台（无代码/低代码） <a class="header-anchor" href="#_4-2-bi-平台-无代码-低代码" aria-label="Permalink to “4.2 BI 平台（无代码/低代码）”">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>定位</th><th>核心优势</th><th>适用团队</th></tr></thead><tbody><tr><td>Grafana</td><td>监控可视化</td><td>时序数据支持好，告警集成</td><td>运维/SRE 团队</td></tr><tr><td>Metabase</td><td>轻量 BI</td><td>开源免费，SQL 即可出图</td><td>中小团队快速搭建</td></tr><tr><td>Apache Superset</td><td>企业 BI</td><td>开源，支持大数据源</td><td>有数据团队的公司</td></tr><tr><td>Tableau</td><td>商业 BI</td><td>拖拽式操作，可视化效果好</td><td>业务分析师</td></tr><tr><td>Power BI</td><td>商业 BI</td><td>与微软生态集成好</td><td>使用微软技术栈的企业</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">选型建议</p><ul><li><strong>开发者做产品内嵌图表</strong> → ECharts（中文生态好）或 Chart.js（简单场景）</li><li><strong>数据分析师做探索分析</strong> → Plotly + Jupyter 或 Metabase</li><li><strong>运维监控大屏</strong> → Grafana（事实标准）</li><li><strong>业务团队自助分析</strong> → Metabase（开源）或 Tableau（商业）</li><li><strong>需要高度定制</strong> → D3.js（学习曲线陡峭，但无所不能）</li></ul></div><hr><h2 id="_5-常见陷阱-这些图表在骗你" tabindex="-1">5. 常见陷阱：这些图表在骗你 <a class="header-anchor" href="#_5-常见陷阱-这些图表在骗你" aria-label="Permalink to “5. 常见陷阱：这些图表在骗你”">​</a></h2><p>数据可视化是一把双刃剑——用得好能揭示真相，用得不好会制造谎言。以下是最常见的可视化陷阱，每个数据从业者都应该能识别。</p><h3 id="_5-1-截断坐标轴" tabindex="-1">5.1 截断坐标轴 <a class="header-anchor" href="#_5-1-截断坐标轴" aria-label="Permalink to “5.1 截断坐标轴”">​</a></h3><p>把 Y 轴的起点从 0 改成一个较大的数字，会让微小的差异看起来像巨大的变化。</p><table tabindex="0"><thead><tr><th>场景</th><th>真实差异</th><th>视觉感受</th></tr></thead><tbody><tr><td>Y 轴从 0 开始</td><td>A 产品 98 分，B 产品 95 分</td><td>差距很小</td></tr><tr><td>Y 轴从 90 开始</td><td>同样的数据</td><td>A 看起来是 B 的好几倍</td></tr></tbody></table><p><strong>什么时候可以截断？</strong> 当数据的绝对值很大但变化很小时（如股价从 100 到 105），截断是合理的——但必须明确标注。</p><h3 id="_5-2-3d-饼图的透视陷阱" tabindex="-1">5.2 3D 饼图的透视陷阱 <a class="header-anchor" href="#_5-2-3d-饼图的透视陷阱" aria-label="Permalink to “5.2 3D 饼图的透视陷阱”">​</a></h3><p>3D 透视会让靠近观察者的扇区看起来更大。一个 25% 的扇区在 3D 视角下可能看起来像 35%。</p><p><strong>解决方案</strong>：永远不要用 3D 饼图。用普通饼图或环形图，或者干脆用柱状图。</p><h3 id="_5-3-颜色滥用" tabindex="-1">5.3 颜色滥用 <a class="header-anchor" href="#_5-3-颜色滥用" aria-label="Permalink to “5.3 颜色滥用”">​</a></h3><table tabindex="0"><thead><tr><th>错误做法</th><th>正确做法</th></tr></thead><tbody><tr><td>用红绿表示数据（色盲不友好）</td><td>用蓝橙等色盲安全配色</td></tr><tr><td>每个类别用不同颜色（彩虹图）</td><td>同一系列用同色系深浅变化</td></tr><tr><td>用颜色编码连续数据但不加图例</td><td>始终提供颜色图例和数值标注</td></tr><tr><td>背景色和数据色对比度不够</td><td>确保 WCAG AA 级对比度</td></tr></tbody></table><h3 id="_5-4-其他常见错误" tabindex="-1">5.4 其他常见错误 <a class="header-anchor" href="#_5-4-其他常见错误" aria-label="Permalink to “5.4 其他常见错误”">​</a></h3><table tabindex="0"><thead><tr><th>陷阱</th><th>问题</th><th>修复</th></tr></thead><tbody><tr><td>双 Y 轴</td><td>两个不相关的指标共享 X 轴，暗示因果关系</td><td>拆成两张图，或明确说明无因果</td></tr><tr><td>面积误导</td><td>用圆的半径而非面积表示数值</td><td>数值翻倍时面积翻倍，不是半径翻倍</td></tr><tr><td>时间轴不均匀</td><td>1月、3月、12月的间距一样</td><td>按实际时间比例排列</td></tr><tr><td>过多类别</td><td>饼图有 15 个扇区</td><td>超过 5 个类别就用柱状图或合并&quot;其他&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">可视化的道德准则</p><p>可视化的目的是<strong>帮助理解</strong>，不是<strong>操纵认知</strong>。每次做图表时问自己：</p><ul><li>如果我是读者，这张图会不会让我产生错误的结论？</li><li>我是否隐藏了不利的数据？</li><li>坐标轴、比例、颜色是否公正地呈现了数据？</li></ul></div><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>数据可视化是数据价值传递的&quot;最后一公里&quot;。选对图表、遵循设计原则、避免常见陷阱，就能让数据真正&quot;说话&quot;。</p><p>回顾本章的关键要点：</p><ol><li><strong>先问目的再选图表</strong>：比较用柱状图、趋势用折线图、占比用饼图</li><li><strong>数据墨水比</strong>：删掉一切不传达信息的视觉元素</li><li><strong>仪表盘有模式</strong>：概览型、对比型、下钻型、实时型各有适用场景</li><li><strong>工具按需选</strong>：ECharts 做产品、Grafana 做监控、Metabase 做分析</li><li><strong>警惕视觉陷阱</strong>：截断坐标轴、3D 饼图、颜色滥用都会误导读者</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">ECharts 官方文档</a> - 最流行的中文图表库</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - 数据驱动的可视化库</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - 开源监控可视化平台</li><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Tufte 的可视化经典</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - 图表类型选择指南</li></ul><hr><h2 id="总结-1" tabindex="-1">总结 <a class="header-anchor" href="#总结-1" aria-label="Permalink to “总结”">​</a></h2><p>数据可视化是数据价值传递的&quot;最后一公里&quot;。再好的分析，如果不能被正确理解，就等于没有分析。</p><p>回顾本章的关键要点：</p><ol><li><strong>选对图表</strong>：根据数据目的（比较、趋势、占比、分布、关系）选择图表类型</li><li><strong>设计原则</strong>：高数据墨水比、一致性、可读性是三大核心原则</li><li><strong>仪表盘布局</strong>：概览型、对比型、下钻型、实时型四种模式覆盖大部分场景</li><li><strong>工具选型</strong>：从 ECharts 到 Grafana，根据团队能力和需求复杂度选择</li><li><strong>避免陷阱</strong>：截断坐标轴、3D 饼图、颜色滥用是最常见的误导手段</li></ol><h2 id="延伸阅读-1" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读-1" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Edward Tufte 的可视化经典</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">ECharts 官方文档</a> - 最流行的中文图表库</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - 最强大的底层可视化库</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - 监控可视化事实标准</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - 图表类型选择决策树</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - 色盲安全的配色方案工具</li></ul>',46))])}const m=o(n,[["render",h]]);export{f as __pageData,m as default};
